// BackendServiceServer is the server API for BackendService service.
// All implementations should embed UnimplementedBackendServiceServer
// for forward compatibility
type BackendServiceServer interface {
	UpdateIndividualKYC(context.Context, *UpdateIndividualKYCRequest) (*Empty, error)
	GetIndividualKYC(context.Context, *Empty) (*IndividualKYCResponse, error)
	IsUSPSAddress(context.Context, *Address) (*IsUSPSAddressResponse, error)
	SetSignupUserData(context.Context, *SetSignupUserDataRequest) (*SetSignupUserDataResponse, error)
	SetSignupMobileNumber(context.Context, *SetSignupMobileNumberRequest) (*Empty, error)
	// Returns the current signup flow.
	GetSignup(context.Context, *GetSignupRequest) (*Signup, error)
	// Called after the user is created on Kratos with the new userID.
	CompleteSignup(context.Context, *CompleteSignupRequest) (*Empty, error)
	CreateUserDefaultWallet(context.Context, *CreateUserDefaultWalletRequest) (*Empty, error)
	// Wallet
	SetWalletName(context.Context, *SetWalletNameRequest) (*Empty, error)
	GetWalletInfo(context.Context, *Empty) (*WalletInfo, error)
	GetPublicWalletInfo(context.Context, *GetPublicWalletInfoRequest) (*PublicWalletInfo, error)
	// Allows sending and checking an sms verification.
	SendPhoneVerification(context.Context, *SendPhoneVerificationRequest) (*Empty, error)
	SendOTP(context.Context, *Empty) (*Empty, error)
	// Allows signing agreements and getting agreements by id.
	GetAgreement(context.Context, *GetAgreementRequest) (*Agreement, error)
	SignAgreements(context.Context, *SignAgreementsRequest) (*SignAgreementsResponse, error)
	GetLinkedAccounts(context.Context, *Empty) (*GetLinkedAccountsResponse, error)
	GetLinkedAccount(context.Context, *GetLinkedAccountRequest) (*LinkedAccount, error)
	SetNicknameLinkedAccount(context.Context, *SetNicknameLinkedAccountRequest) (*LinkedAccount, error)
	DeleteLinkedAccount(context.Context, *DeleteLinkedAccountRequest) (*Empty, error)
	CreateSupportTicket(context.Context, *CreateSupportTicketRequest) (*Empty, error)
	GetCountries(context.Context, *Empty) (*GetCountriesResponse, error)
	GetCurrentWallet(context.Context, *Empty) (*GetCurrentWalletResponse, error)
	//Waitlist
	JoinWaitlist(context.Context, *JoinWaitlistRequest) (*JoinWaitlistResponse, error)
	CanSignup(context.Context, *CanSignupRequest) (*CanSignupResponse, error)
	SetSignupComplete(context.Context, *SetSignupCompleteRequest) (*Empty, error)
	IsMugAvailable(context.Context, *IsMugAvailableRequest) (*IsMugAvailableResponse, error)
	//Transactions
	ListTransactions(context.Context, *PaginationRequest) (*ListTransactionsResponse, error)
	ListTransactionsCompleted(context.Context, *PaginationRequest) (*ListTransactionsResponse, error)
	ListTransactionsWithPending(context.Context, *PaginationRequest) (*ListTransactionsResponse, error)
	LookupTransaction(context.Context, *LookupTransactionRequest) (*Transaction, error)
	// Limits GNAP
	ListLimits(context.Context, *Empty) (*ListLimitsResponse, error)
	UpdateClientLimits(context.Context, *UpdateClientLimitsRequest) (*Empty, error)
	//Connections
	CreateConnection(context.Context, *CreateConnectionRequest) (*Empty, error)
	ListConnections(context.Context, *Empty) (*ListConnectionsResponse, error)
	GetConnection(context.Context, *GetConnectionRequest) (*Connection, error)
	GetConnectionLimits(context.Context, *GetConnectionLimitsRequest) (*ConnectionLimits, error)
	UpdateConnectionLimits(context.Context, *UpdateConnectionLimitsRequest) (*Empty, error)
	DeleteConnection(context.Context, *DeleteConnectionRequest) (*Empty, error)
	// Public Wallet Data
	GetPublicWalletDetails(context.Context, *GetPublicWalletDetailsRequest) (*GetPublicWalletDetailsResponse, error)
	// Contacts
	CreateContact(context.Context, *CreateContactRequest) (*Contact, error)
	ListContacts(context.Context, *ListContactsRequest) (*ListContactsResponse, error)
	// Identities
	ListIdentities(context.Context, *Empty) (*ListIdentitiesResponse, error)
	ListPublicIdentities(context.Context, *ListPublicIdentitiesRequest) (*ListIdentitiesResponse, error)
	DeleteIdentity(context.Context, *DeleteIdentityRequest) (*Empty, error)
	SetIdentityPublic(context.Context, *SetIdentityPublicRequest) (*Identity, error)
	GetIdentity(context.Context, *GetIdentityRequest) (*GetIdentityResponse, error)
	GetIdentityBySignatureHash(context.Context, *GetIdentityBySignatureHashRequest) (*GetIdentityResponse, error)
	// KYC
	KYCStatus(context.Context, *Empty) (*KYCStatusResponse, error)
	SetKYCStatusPending(context.Context, *Empty) (*Empty, error)
	StartKYC(context.Context, *Empty) (*Empty, error)
	GetPersonaInquiry(context.Context, *KYCPersonaInquiryRequest) (*KYCPersonaInquiryResponse, error)
	// MX
	GetMXWidget(context.Context, *Empty) (*MXWidgetResponse, error)
	CreateMXBankAccounts(context.Context, *CreateMXBankAccountsRequest) (*CreateMXBankAccountsResponse, error)
	// GMT
	OnboardGMTUser(context.Context, *Empty) (*Empty, error)
	// Tabapay 3DS
	Init3DS(context.Context, *Init3DSRequest) (*Init3DSResponse, error)
	Lookup3DS(context.Context, *Lookup3DSRequest) (*Lookup3DSResponse, error)
	Authenticate3DS(context.Context, *Authenticate3DSRequest) (*Authenticate3DSResponse, error)
	// Basistheory
	CreateCard(context.Context, *CreateCardRequest) (*LinkedAccount, error)
	GetCardDetails(context.Context, *GetCardDetailsRequest) (*CardDetails, error)
	// Features
	ListFeatures(context.Context, *Empty) (*Features, error)
	// Twitter
	CreateTwitterAuthURL(context.Context, *Empty) (*CreateTwitterAuthURLResponse, error)
	TwitterCallback(context.Context, *TwitterCallbackRequest) (*TwitterCallbackResponse, error)
	VerifyTwitter(context.Context, *VerifyTwitterRequest) (*Empty, error)
	// Payments
	GetPaymentAddress(context.Context, *GetPaymentAddressRequest) (*GetPaymentAddressResponse, error)
	// Search
	SearchWallets(context.Context, *SearchWalletsRequest) (*SearchWalletsResponse, error)
}

